m<-fread(file.path(V,'00_audit/manifest.csv'))[tissue_origin=='Tumor'];db<-r('00_input_audit/DB_components.csv');act1<-fread(file.path(N1,'04_NicheNet_ligand_activity/all_program_activities.tsv'));act2<-fread(file.path(N2,'03_nominal_NicheNet/all_activities.tsv'));acts<-rbindlist(list(act1[,source:='standard'],act2[,source:='nominal']),fill=TRUE);w(acts,'tables/NicheNet_activities.csv')
np<-fread(file.path(N2,'00_input_audit/official_human_v2_LR_pairs.tsv'));ligs<-unique(c(FOCUS,acts[rank<=20,test_ligand]));ng<-unique(np[ligand%in%ligs,receptor]);rg<-unique(unlist(strsplit(db[ligand%in%FOCUS,receptor_genes],';',fixed=TRUE)));genes<-sort(unique(c(ligs,rg,ng)));w(data.table(gene=genes),'00_input_audit/expression_requested_genes.csv');rows<-list();viols<-list();qc<-list();vgenes<-c('POSTN','FN1','HSPG2','SEMA3C','MDK','ADM')
for(i in seq_len(nrow(m))){
 cat('EXPRESSION ',i,'/',nrow(m),' ',m$specimen_id[i],'\n');flush.console();z<-qs2::qs_read(m$input_path[i],nthreads=1);md<-as.data.table(z$metadata);stopifnot(identical(colnames(z$expression),md$cell),all(md$cellchat_group%in%G));gs<-intersect(genes,rownames(z$expression));qc[[i]]<-data.table(specimen_id=m$specimen_id[i],cells=nrow(md),requested=length(genes),found=length(gs),missing=paste(setdiff(genes,gs),collapse=';'))
 for(g in G){ix<-which(md$cellchat_group==g);if(!length(ix))next;a<-z$expression[gs,ix,drop=FALSE];rows[[length(rows)+1]]<-data.table(gene=gs,group=g,specimen_id=m$specimen_id[i],patient_id=m$patient_id[i],dataset=m$dataset[i],clinical_group=m$clinical_group[i],n_cells=length(ix),detected=as.numeric(rowSums(a>0)),sum_log=as.numeric(rowSums(a)))
 if(g%in%FIB){vg<-intersect(vgenes,gs);vv<-as.data.table(as.table(as.matrix(z$expression[vg,ix,drop=FALSE])));setnames(vv,c('gene','cell','expression'));vv[,`:=`(group=g,specimen_id=m$specimen_id[i],patient_id=m$patient_id[i],dataset=m$dataset[i])];viols[[length(viols)+1]]<-vv}
 };rm(z);gc(FALSE)
}
x<-rbindlist(rows);w(x,'tables/expression_specimen.csv.gz');p<-x[,.(n_cells=sum(n_cells),detected=sum(detected),sum_log=sum(sum_log)),by=.(gene,group,patient_id,dataset,clinical_group)];p[,`:=`(fraction=detected/n_cells,mean_expression=sum_log/n_cells)];w(p,'tables/expression_patient.csv.gz');s<-p[,.(cell_mean=sum(sum_log)/sum(n_cells),cell_fraction=sum(detected)/sum(n_cells),patient_mean=mean(mean_expression),patient_fraction=mean(fraction),n_cells=sum(n_cells),n_patients=uniqueN(patient_id),n_patient_units=.N),by=.(gene,group)];w(s,'tables/expression_summary.csv');w(rbindlist(viols),'tables/violin_cells.csv.gz');w(rbindlist(qc),'00_input_audit/expression_cache_checks.csv')
# Common specimens for expression comparison, then patients; >=5 cells in each fibro group.
x<-x[gene%in%FOCUS&group%in%FIB&n_cells>=5];x[,mean_expression:=sum_log/n_cells];cmp<-list();for(o in setdiff(FIB,C5)){a<-x[group==C5];b<-x[group==o];v<-merge(a,b[,.(gene,specimen_id,other_mean=mean_expression)],by=c('gene','specimen_id'));v[,difference:=mean_expression-other_mean];u<-v[,.(C5=q(mean_expression),other_mean=q(other_mean),difference=q(difference),n_specimens=.N),by=.(gene,patient_id,dataset,clinical_group)];u[,other:=o];cmp[[o]]<-u};cc<-rbindlist(cmp);w(cc,'tables/expression_common_patient_pairs.csv');ss<-cc[,.(median_difference=q(difference),q25=q(difference,.25),q75=q(difference,.75),n_patients=uniqueN(patient_id),fraction_positive=mean(difference>0)),by=.(gene,other)];w(ss,'tables/expression_common_summary.csv');cat('EXPRESSION COMPLETE\n')
